1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ee; font: 15px/1.4 system-ui, sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; background: #2a2d36; border: 2px solid #3a3e4a;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #1c1f27; }
20	  .side { display: flex; flex-direction: column; gap: 14px; min-width: 130px; }
21	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: #8a8fa0; }
22	  .stat .value { font-size: 22px; font-weight: 600; }
23	  .preview { display: grid; grid-template-columns: repeat(4, 18px); grid-template-rows: repeat(2, 18px); gap: 1px; margin-bottom: 8px; }
24	  .preview .mini { width: 18px; height: 18px; background: transparent; }
25	  .help { font-size: 12px; color: #8a8fa0; }
26	  .p-I { background: #00c8e0 !important; }
27	  .p-O { background: #f0d000 !important; }
28	  .p-T { background: #a040f0 !important; }
29	  .p-S { background: #30c050 !important; }
30	  .p-Z { background: #e03030 !important; }
31	  .p-J { background: #3060f0 !important; }
32	  .p-L { background: #f08c20 !important; }
33	</style>
34	</head>
35	<body>
36	<div class="game">
37	  <div class="board" data-testid="board" id="board"></div>
38	  <div class="side">
39	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
40	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
41	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
42	    <div class="stat"><div class="label">Next</div><div id="next"></div></div>
43	    <div class="help">← → move<br>↑ or X rotate<br>↓ soft drop<br>Space hard drop</div>
44	  </div>
45	</div>
46	<script>
47	(function () {
48	  var ROWS = 20, COLS = 10, LETTERS = ["I", "O", "T", "S", "Z", "J", "L"];
49	
50	  // [REQ-001] spawn shapes as [row, col] on the board
51	  var SHAPES = {
52	    I: [[0, 3], [0, 4], [0, 5], [0, 6]],
53	    O: [[0, 4], [0, 5], [1, 4], [1, 5]],
54	    T: [[0, 4], [1, 3], [1, 4], [1, 5]],
55	    S: [[0, 4], [0, 5], [1, 3], [1, 4]],
56	    Z: [[0, 3], [0, 4], [1, 4], [1, 5]],
57	    J: [[0, 3], [1, 3], [1, 4], [1, 5]],
58	    L: [[0, 5], [1, 3], [1, 4], [1, 5]]
59	  };
60	
61	  // [REQ-002] rotation box per piece: size and spawn origin (top-left of the box on the board)
62	  var BOX = {
63	    I: { size: 4, origin: [-1, 3] },
64	    O: { size: 2, origin: [0, 4] },
65	    T: { size: 3, origin: [0, 3] }, S: { size: 3, origin: [0, 3] }, Z: { size: 3, origin: [0, 3] },
66	    J: { size: 3, origin: [0, 3] }, L: { size: 3, origin: [0, 3] }
67	  };
68	  var KICKS = [0, -1, 1, -2, 2];  // sideways shifts tried when a rotation does not fit
69	  var LOCK_TICKS = 2;             // [REQ-002] ticks unable to fall before a piece locks
70	  var MAX_LOCK_RESETS = 3;        // [REQ-002] lock delay restarts allowed per piece
71	  // [REQ-003] points per clear by rows at once, times level; clearing together always beats one at a time
72	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
73	  var SOFT_DROP_POINTS = 1, HARD_DROP_POINTS = 2;  // [REQ-003] per cell moved down by the player
74	
75	  var state = {
76	    board: [],      // board[row][col] = letter or null
77	    current: null,  // { type, cells: [[r,c],...], origin: [r,c], lockTicks, lockResets }
78	    upcoming: [],
79	    score: 0, level: 1, lines: 0,
80	    status: "running"
81	  };
82	  var timer = null;
83	
84	  var boardEl = document.getElementById("board");
85	  var cellEls = [];
86	  for (var r = 0; r < ROWS; r++) {
87	    cellEls.push([]);
88	    for (var c = 0; c < COLS; c++) {
89	      var el = document.createElement("div");
90	      el.className = "cell";
91	      el.setAttribute("data-testid", "cell");
92	      el.setAttribute("data-row", r);
93	      el.setAttribute("data-col", c);
94	      boardEl.appendChild(el);
95	      cellEls[r].push(el);
96	    }
97	  }
98	
99	  function emptyBoard() {
100	    var b = [];
101	    for (var r = 0; r < ROWS; r++) { b.push(new Array(COLS).fill(null)); }
102	    return b;
103	  }
104	
105	  function randomLetter() {
106	    return LETTERS[Math.floor(Math.random() * LETTERS.length)];
107	  }
108	
109	  function validLetters(queue) {
110	    return (Array.isArray(queue) ? queue : []).filter(function (l) { return SHAPES[l]; });
111	  }
112	
113	  // [REQ-001] take the next piece from the queue, falling back to random
114	  function takeNext() {
115	    var letter = state.upcoming.length ? state.upcoming.shift() : randomLetter();
116	    if (!state.upcoming.length) state.upcoming.push(randomLetter());
117	    return letter;
118	  }
119	
120	  function spawn() {
121	    var type = takeNext();
122	    state.current = {
123	      type: type,
124	      cells: SHAPES[type].map(function (p) { return [p[0], p[1]]; }),
125	      origin: BOX[type].origin.slice(),
126	      lockTicks: 0, lockResets: 0
127	    };
128	  }
129	
130	  function fits(cells) {
131	    return cells.every(function (p) {
132	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !state.board[p[0]][p[1]];
133	    });
134	  }
135	
136	  function canMove(dr, dc) {
137	    return fits(state.current.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; }));
138	  }
139	
140	  function tryMove(dr, dc) {
141	    if (!state.current || !canMove(dr, dc)) return false;
142	    var cur = state.current;
143	    cur.cells = cur.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; });
144	    cur.origin = [cur.origin[0] + dr, cur.origin[1] + dc];
145	    if (dr > 0) cur.lockTicks = 0;
146	    return true;
147	  }
148	
149	  // [REQ-002] rotate clockwise inside the piece's box; try sideways shifts; refuse if nothing fits
150	  function tryRotateCW() {
151	    var cur = state.current, n = BOX[cur.type].size, o = cur.origin;
152	    var turned = cur.cells.map(function (p) {
153	      var lr = p[0] - o[0], lc = p[1] - o[1];
154	      return [o[0] + lc, o[1] + n - 1 - lr];
155	    });
156	    // a rotation near the top edge is pushed down just enough to stay on the board
157	    var dr = Math.max(0, -Math.min.apply(null, turned.map(function (p) { return p[0]; })));
158	    for (var i = 0; i < KICKS.length; i++) {
159	      var dc = KICKS[i];
160	      var cand = turned.map(function (p) { return [p[0] + dr, p[1] + dc]; });
161	      if (fits(cand)) {
162	        cur.cells = cand;
163	        cur.origin = [o[0] + dr, o[1] + dc];
164	        return true;
165	      }
166	    }
167	    return false;
168	  }
169	
170	  // [REQ-002] sideways move; while resting it restarts the lock delay, at most MAX_LOCK_RESETS times
171	  function shift(dc) {
172	    var resting = !canMove(1, 0);
173	    if (!tryMove(0, dc) || !resting) return;
174	    var cur = state.current;
175	    if (cur.lockResets < MAX_LOCK_RESETS) { cur.lockResets++; cur.lockTicks = 0; }
176	  }
177	
178	  // [REQ-003] remove full rows, drop everything above, count lines and score the clear
179	  function clearLines() {
180	    var kept = state.board.filter(function (row) { return !row.every(Boolean); });
181	    var cleared = ROWS - kept.length;
182	    if (!cleared) return;
183	    while (kept.length < ROWS) kept.unshift(new Array(COLS).fill(null));
184	    state.board = kept;
185	    state.lines += cleared;
186	    state.score += CLEAR_POINTS[cleared] * state.level;
187	  }
188	
189	  // [REQ-001] [REQ-003] lock the falling piece, clear full rows and spawn the next one
190	  function lock() {
191	    var cur = state.current;
192	    cur.cells.forEach(function (p) {
193	      if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) state.board[p[0]][p[1]] = cur.type;
194	    });
195	    clearLines();
196	    spawn();
197	  }
198	
199	  // [REQ-001] [REQ-002] one gravity step: fall one row, or count one tick of lock delay
200	  function gravityStep() {
201	    if (state.status !== "running") return;
202	    if (!state.current) spawn();
203	    else if (!tryMove(1, 0) && ++state.current.lockTicks >= LOCK_TICKS) lock();
204	    render();
205	  }
206	
207	  // [REQ-001] [REQ-002] [REQ-003] player actions; hard drop locks at once, with no delay; drops score per cell
208	  function input(action) {
209	    if (state.status !== "running" || !state.current) return;
210	    if (action === "left") shift(-1);
211	    else if (action === "right") shift(1);
212	    else if (action === "rotateCW") tryRotateCW();
213	    else if (action === "softDrop") { if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS; }
214	    else if (action === "hardDrop") {
215	      while (tryMove(1, 0)) state.score += HARD_DROP_POINTS;
216	      lock();
217	    }
218	    render();
219	  }
220	
221	  // [REQ-001] synchronous render from the real game state
222	  function render() {
223	    var drawn = state.board.map(function (row) { return row.slice(); });
224	    if (state.current) {
225	      state.current.cells.forEach(function (p) {
226	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) drawn[p[0]][p[1]] = state.current.type;
227	      });
228	    }
229	    for (var r = 0; r < ROWS; r++) {
230	      for (var c = 0; c < COLS; c++) {
231	        var el = cellEls[r][c], letter = drawn[r][c];
232	        el.className = letter ? "cell p-" + letter : "cell";
233	        el.setAttribute("data-filled", letter ? "true" : "false");
234	        el.setAttribute("data-piece", letter || "");
235	      }
236	    }
237	    document.getElementById("score").textContent = String(state.score);
238	    document.getElementById("level").textContent = String(state.level);
239	    document.getElementById("lines").textContent = String(state.lines);
240	    renderNext();
241	  }
242	
243	  function renderNext() {
244	    var box = document.getElementById("next");
245	    box.innerHTML = "";
246	    state.upcoming.slice(0, 3).forEach(function (type) {
247	      var grid = document.createElement("div");
248	      grid.className = "preview";
249	      var filled = {};
250	      SHAPES[type].forEach(function (p) { filled[p[0] + "," + (p[1] - 3)] = true; });
251	      for (var r = 0; r < 2; r++) {
252	        for (var c = 0; c < 4; c++) {
253	          var m = document.createElement("div");
254	          m.className = filled[r + "," + c] ? "mini p-" + type : "mini";
255	          grid.appendChild(m);
256	        }
257	      }
258	      box.appendChild(grid);
259	    });
260	  }
261	
262	  function startTimer() {
263	    if (timer) clearInterval(timer);
264	    timer = setInterval(gravityStep, 1000);
265	  }
266	
267	  // [REQ-001] start a fresh game, optionally with a fixed piece queue
268	  function newGame(queue) {
269	    state.board = emptyBoard();
270	    state.score = 0; state.level = 1; state.lines = 0;
271	    state.status = "running";
272	    state.upcoming = validLetters(queue);
273	    state.current = null;
274	    spawn();
275	    startTimer();
276	    render();
277	  }
278	
279	  // [REQ-001] test control surface
280	  window.__tetris = {
281	    newGame: newGame,
282	    setQueue: function (queue) {
283	      state.upcoming = validLetters(queue);
284	      render();
285	    },
286	    setBoard: function (rows) {
287	      var b = emptyBoard();
288	      for (var r = 0; r < ROWS; r++) {
289	        var line = (rows && rows[r]) || "";
290	        for (var c = 0; c < COLS; c++) {
291	          var ch = line.charAt(c);
292	          b[r][c] = SHAPES[ch] ? ch : null;
293	        }
294	      }
295	      state.board = b;
296	      render();
297	    },
298	    tick: function (n) {
299	      if (n === undefined) n = 1;
300	      for (var i = 0; i < n; i++) gravityStep();
301	    },
302	    input: input,
303	    getBoard: function () {
304	      return state.board.map(function (row) {
305	        return row.map(function (v) { return v || "."; }).join("");
306	      });
307	    },
308	    getState: function () {
309	      return {
310	        current: state.current
311	          ? {
312	              type: state.current.type,
313	              cells: state.current.cells.map(function (p) { return [p[0], p[1]]; }),
314	              lockTicks: state.current.lockTicks,
315	              lockResets: state.current.lockResets
316	            }
317	          : null,
318	        next: state.upcoming.slice(),
319	        score: state.score, level: state.level, lines: state.lines,
320	        status: state.status
321	      };
322	    }
323	  };
324	
325	  document.addEventListener("keydown", function (e) {
326	    var map = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", x: "rotateCW", X: "rotateCW", " ": "hardDrop", Spacebar: "hardDrop" };
327	    var action = map[e.key];
328	    if (!action) return;
329	    e.preventDefault();
330	    input(action);
331	  });
332	
333	  newGame();
334	})();
335	</script>
336	</body>
337	</html>
