python3 - <<'EOF'
p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''  .help { font-size: 12px; color: #8a8fa0; }''','''  .help { font-size: 12px; color: #8a8fa0; }
  .game-over { font-size: 18px; font-weight: 700; color: #ff6b6b; }''')
rep('''<div id="next"></div></div>''','''<div id="next" data-testid="next-piece"></div></div>
    <div class="game-over" data-testid="game-over" id="game-over" hidden>Game over</div>''')
rep('''  var SOFT_DROP_POINTS = 1, HARD_DROP_POINTS = 2;  // [REQ-003] per cell moved down by the player
''','''  var SOFT_DROP_POINTS = 1, HARD_DROP_POINTS = 2;  // [REQ-003] per cell moved down by the player
  var PREVIEW_COUNT = 3;          // [REQ-004] upcoming pieces shown in the preview
''')
rep('''  // [REQ-001] take the next piece from the queue, falling back to random
  function takeNext() {
    var letter = state.upcoming.length ? state.upcoming.shift() : randomLetter();
    if (!state.upcoming.length) state.upcoming.push(randomLetter());
    return letter;
  }

  function spawn() {
    var type = takeNext();
    state.current = {
      type: type,
      cells: SHAPES[type].map(function (p) { return [p[0], p[1]]; }),
      origin: BOX[type].origin.slice(),
      lockTicks: 0, lockResets: 0
    };
  }''','''  // [REQ-004] keep enough upcoming pieces to fill the preview, padding with random ones
  function fillUpcoming() {
    while (state.upcoming.length < PREVIEW_COUNT) state.upcoming.push(randomLetter());
  }

  // [REQ-001] take the next piece from the queue, falling back to random
  function takeNext() {
    var letter = state.upcoming.length ? state.upcoming.shift() : randomLetter();
    fillUpcoming();
    return letter;
  }

  // [REQ-004] a new piece that does not fit where it spawns ends the game
  function spawn() {
    var type = takeNext();
    var cells = SHAPES[type].map(function (p) { return [p[0], p[1]]; });
    if (!fits(cells)) {
      state.current = null;
      state.status = "gameover";
      if (timer) { clearInterval(timer); timer = null; }
      return;
    }
    state.current = {
      type: type,
      cells: cells,
      origin: BOX[type].origin.slice(),
      lockTicks: 0, lockResets: 0
    };
  }''')
rep('''    renderNext();
  }''','''    renderNext();
    document.getElementById("game-over").hidden = state.status !== "gameover";
  }''')
rep('''  function renderNext() {
    var box = document.getElementById("next");
    box.innerHTML = "";
    state.upcoming.slice(0, 3).forEach(function (type) {
      var grid = document.createElement("div");
      grid.className = "preview";''','''  // [REQ-004] next three pieces, soonest first, coloured as on the board
  function renderNext() {
    var box = document.getElementById("next");
    box.innerHTML = "";
    state.upcoming.slice(0, PREVIEW_COUNT).forEach(function (type) {
      var grid = document.createElement("div");
      grid.className = "preview";
      grid.setAttribute("data-testid", "next-piece-item");
      grid.setAttribute("data-piece", type);''')
rep('''      state.upcoming = validLetters(queue);
      render();''','''      state.upcoming = validLetters(queue);
      fillUpcoming();
      render();''')
open(p,'w').write(s)
EOF
sed -n '/<script>/,/<\/script>/p' index.html | sed '1d;$d' > "$TMPDIR/t.js" 2>/dev/null || true; node --check "$TMPDIR/t.js" && echo ok
